function Config.GuildDunData.data_chapter_reward_fun(slot0)
	slot1 = Config.GuildDunData.data_chapter_reward[slot0]

	if DATA_DEBUG and slot1 == nil then
		print("(Config.GuildDunData.data_chapter_reward[" .. slot0 .. "])not found")

		return
	end

	return slot1
end

