function Config.GuildDunData.data_chapter_box_fun(slot0)
	slot1 = Config.GuildDunData.data_chapter_box[slot0]

	if DATA_DEBUG and slot1 == nil then
		print("(Config.GuildDunData.data_chapter_box[" .. slot0 .. "])not found")

		return
	end

	return slot1
end

